    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KK-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gecikme süresi, sisteme girdi verilerek ve harita üzerindeki görsel çıktı zamanlaması ölçülerek doğrulanabilir."
    },
    {
      "requirement_id": "KK-002",
      "methods": [
        "Test"
      ],
      "rationale": "Yük testi ile 2.000 izin aynı anda görüntülenmesi ve ekran yenileme hızının 10 Hz üzerinde kalıp kalmadığı gözlemlenerek doğrulanır."
    },
    {
      "requirement_id": "KK-003",
      "methods": [
        "Test"
      ],
      "rationale": "Operatörün bir izi seçmesi ve ilgili detayların ekranda doğru şekilde görüntülenmesi, sistem çalıştırılarak ve girdi verilerek test edilir."
    },
    {
      "requirement_id": "KK-004",
      "methods": [
        "Test"
      ],
      "rationale": "Güncelleme akışının durdurulmasıyla 30 ve 120 saniye sonrası iz durumunun değişimi, sistem çalıştırılarak gözlemlenir."
    },
    {
      "requirement_id": "KK-005",
      "methods": [
        "Test"
      ],
      "rationale": "Tanımlı bölgeye iz girdiğinde görsel ve sesli uyarıların tetiklenmesi, sistem çalıştırılarak ve senaryo uygulanarak doğrulanır."
    },
    {
      "requirement_id": "KK-006",
      "methods": [
        "Test"
      ],
      "rationale": "Mesaj gönderimi sonrası iletim süresi ve durum bildiriminin alıcıya ulaşması, sistem üzerinden işlem yapılarak gözlemlenir."
    },
    {
      "requirement_id": "KK-007",
      "methods": [
        "Test",
        "İnceleme"
      ],
      "rationale": "Kayıt işleminin çalışması test edilirken, logların değiştirilemezlik özelliği ve formatı kod veya yapılandırma incelemesiyle doğrulanır."
    },
    {
      "requirement_id": "KK-008",
      "methods": [
        "Test"
      ],
      "rationale": "Birincil sunucunun durdurulmasıyla yedek sunucunun devralma süresi ve veri bütünlüğü, sistem çalıştırılarak ve arıza senaryosu uygulanarak test edilir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": [
        "Test"
      ],
      "rationale": "Sistemin e-Devlet entegrasyonu ile oturum açma işlevinin çalışıp çalışmadığı, gerçek veya simüle edilmiş kimlik doğrulama girdileri verilerek gözlemlenmelidir."
    },
    {
      "requirement_id": "KMU-002",
      "methods": [
        "Test"
      ],
      "rationale": "15 dakikalık inaktivite süresinin sonunda oturumun sonlandırılması ve yönlendirme davranışının, zamanlayıcı testleri ile doğrulanması gerekir."
    },
    {
      "requirement_id": "KMU-003",
      "methods": [
        "Test"
      ],
      "rationale": "Art arda 5 başarısız giriş denemesi sonrası hesap kilitleme mekanizmasının ve 30 dakikalık kilit süresinin, senaryo tabanlı testlerle doğrulanması uygundur."
    },
    {
      "requirement_id": "KMU-004",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut limiti (10 MB) ve adet limiti (5 dosya) kısıtlarının, farklı girdi kombinasyonlarıyla sisteme yüklenerek test edilmesi gerekir."
    },
    {
      "requirement_id": "KMU-005",
      "methods": [
        "Test"
      ],
      "rationale": "Benzersiz takip numarası üretimi ve e-posta bildiriminin gönderilmesi, başvuru tamamlama işlemi sonrası gözlemlenerek test edilmelidir."
    },
    {
      "requirement_id": "KMU-006",
      "methods": [
        "Test"
      ],
      "rationale": "Taslak kaydetme işlevi ve 30 günlük süre içinde kaldığı yerden devam etme özelliğinin, zaman ve veri tutarlılığı testleriyle doğrulanması gerekir."
    },
    {
      "requirement_id": "KMU-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "WCAG 2.1 AA uyumluluğunun, kullanıcı arayüzünün kod yapısı, HTML semantiği ve erişilebilirlik araçlarıyla yapılan denetimler yoluyla incelenmesi gerekir."
    },
    {
      "requirement_id": "KMU-008",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Verilerin yalnızca Türkiye sınırları içindeki sunucularda saklanmasının, altyapı yapılandırma belgeleri ve sunucu konum bilgileri üzerinden incelenerek doğrulanması gerekir."
    }
  ]
}

